% TODO: possibly, in the future, optimize the spatial cross product (i.e.
%  avoid code that computes the whole 6x6 matrix)
function tau = inverseDynamics(ip, xm, qd, qdd, fext)

g = 9.81;

if nargin < 5
    fext = cell(5,1);
    fext(:) = {zeros(6,1)};
end

%
% Pass 1. Forward propagate velocities and accelerations
%

% Link 'link1'
a_link1 = xm.link1_X_base0.mx(:,6) * g;
a_link1(3) = a_link1(3) + qdd(1);
v_link1 = [0;0;qd(1);0;0;0];
w2 = qd(1)*qd(1);
vxIv = [-ip.link1.tensor6D(2,3) * w2; ...
         ip.link1.tensor6D(1,2) * w2; ...
         0; ...
         ip.link1.tensor6D(2,6) * w2; ...
         ip.link1.tensor6D(3,4) * w2; ...
         0];
f_link1 = -fext{1} + ip.link1.tensor6D * a_link1 + vxIv;

% Link 'link2'
v_link2 = ((xm.link2_X_link1.mx) * v_link1);
v_link2(6) = v_link2(6) + qd(2);

vcross = vcross_mx(v_link2);

a_link2 = xm.link2_X_link1.mx * a_link1 + (vcross(:,6) * qd(2));
a_link2(6) = a_link2(6) + qdd(2);

f_link2 = -fext{2} + ip.link2.tensor6D * a_link2 + (-vcross' * ip.link2.tensor6D * v_link2);

% Link 'link3'
v_link3 = ((xm.link3_X_link2.mx) * v_link2);
v_link3(3) = v_link3(3) + qd(3);

vcross = vcross_mx(v_link3);

a_link3 = xm.link3_X_link2.mx * a_link2 + (vcross(:,3) * qd(3));
a_link3(3) = a_link3(3) + qdd(3);

f_link3 = -fext{3} + ip.link3.tensor6D * a_link3 + (-vcross' * ip.link3.tensor6D * v_link3);

% Link 'link4'
v_link4 = ((xm.link4_X_link3.mx) * v_link3);
v_link4(6) = v_link4(6) + qd(4);

vcross = vcross_mx(v_link4);

a_link4 = xm.link4_X_link3.mx * a_link3 + (vcross(:,6) * qd(4));
a_link4(6) = a_link4(6) + qdd(4);

f_link4 = -fext{4} + ip.link4.tensor6D * a_link4 + (-vcross' * ip.link4.tensor6D * v_link4);

% Link 'link5'
v_link5 = ((xm.link5_X_link4.mx) * v_link4);
v_link5(3) = v_link5(3) + qd(5);

vcross = vcross_mx(v_link5);

a_link5 = xm.link5_X_link4.mx * a_link4 + (vcross(:,3) * qd(5));
a_link5(3) = a_link5(3) + qdd(5);

f_link5 = -fext{5} + ip.link5.tensor6D * a_link5 + (-vcross' * ip.link5.tensor6D * v_link5);


%
% Pass 2. Compute the joint torques while back propagating the spatial forces
%
tau = zeros(size(qd));

% Link 'link5'
tau(5) = f_link5(3);
f_link4 = f_link4 + xm.link5_X_link4.mx' * f_link5;

% Link 'link4'
tau(4) = f_link4(6);
f_link3 = f_link3 + xm.link4_X_link3.mx' * f_link4;

% Link 'link3'
tau(3) = f_link3(3);
f_link2 = f_link2 + xm.link3_X_link2.mx' * f_link3;

% Link 'link2'
tau(2) = f_link2(6);
f_link1 = f_link1 + xm.link2_X_link1.mx' * f_link2;

% Link 'link1'
tau(1) = f_link1(3);

end

function vc = vcross_mx(v)
    vc = [   0    -v(3)  v(2)   0     0     0    ;
             v(3)  0    -v(1)   0     0     0    ;
            -v(2)  v(1)  0      0     0     0    ;
             0    -v(6)  v(5)   0    -v(3)  v(2) ;
             v(6)  0    -v(4)   v(3)  0    -v(1) ;
            -v(5)  v(4)  0     -v(2)  v(1)  0    ];
end
